  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {node['id']: node for node in nodes}
    children_map = {node['id']: [] for node in nodes}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children_map[parent].append(node['id'])
    roots = [n['id'] for n in nodes if n['parent'] is None]
    if len(roots) != 1:
        raise ValueError('Must have exactly one root')
    root_id = roots[0]
    all_symbols = set(n['symbol'] for n in nodes)
    for sym in required_symbols:
        if sym not in all_symbols:
            raise ValueError(f'Required symbol {sym} not present in tree')
    retained = set(node['id'] for node in nodes)
    removed = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue
        if nid == root_id:
            continue
        if not node['removable']:
            continue
        has_retained_children = any(child_id in retained for child_id in children_map.get(nid, []))
        if has_retained_children:
            continue
        symbol_counts = {}
        for rid in retained:
            sym = node_map[rid]['symbol']
            symbol_counts[sym] = symbol_counts.get(sym, 0) + 1
        this_sym = node['symbol']
        symbol_counts[this_sym] = symbol_counts.get(this_sym, 0) - 1
        can_remove = True
        for sym in required_symbols:
            if symbol_counts.get(sym, 0) <= 0:
                can_remove = False
                break
        if not can_remove:
            continue
        retained.remove(nid)
        removed.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}
